-- Disposable database only; runner MUST wrap this file in BEGIN / ROLLBACK.
CREATE TEMP TABLE audit_checks(id text, verdict text, observed text);
CREATE FUNCTION pg_temp.check_audit(label text, passed boolean, detail text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN INSERT INTO audit_checks VALUES(label,CASE WHEN passed THEN 'PASS' ELSE 'FAIL' END,detail); END $$;
DO $$
DECLARE a uuid:=gen_random_uuid(); b uuid:=gen_random_uuid(); own uuid:=gen_random_uuid(); rev uuid:=gen_random_uuid(); school uuid; disc uuid; prog uuid; yr uuid; sem uuid; mod uuid; unit uuid; lesson uuid; assessment uuid; attempt uuid; n int; denied boolean;
BEGIN
 INSERT INTO auth.users(id,email) VALUES(a,a||'@example.test'),(b,b||'@example.test'),(own,own||'@example.test'),(rev,rev||'@example.test');
 INSERT INTO profiles(id,email,display_name) SELECT id,email,'Synthetic audit actor' FROM auth.users WHERE id IN(a,b,own,rev);
 INSERT INTO profile_roles(profile_id,role_id) SELECT x.actor,r.id FROM (VALUES(a,'student'),(b,'student'),(own,'platform_owner'),(rev,'engineering_reviewer')) x(actor,role_key) JOIN roles r ON r.role_key::text=x.role_key;
 SELECT id INTO school FROM schools LIMIT 1;
 INSERT INTO disciplines(school_id,slug,title,description) VALUES(school,'audit-discipline','Synthetic fixture','Synthetic fixture') RETURNING id INTO disc;
 INSERT INTO programmes(discipline_id,slug,title,description,publication_status) VALUES(disc,'audit-programme','Synthetic fixture','Synthetic fixture','published') RETURNING id INTO prog;
 INSERT INTO academic_years(programme_id,year_number,title) VALUES(prog,1,'Synthetic fixture') RETURNING id INTO yr;
 INSERT INTO semesters(academic_year_id,semester_number,title) VALUES(yr,1,'Synthetic fixture') RETURNING id INTO sem;
 INSERT INTO modules(semester_id,slug,title,description,difficulty,academic_level,estimated_duration_minutes,technical_review_status,publication_status) VALUES(sem,'fluid-mechanics-foundations','Synthetic fixture','Synthetic fixture','test','test',1,'Approved for student use','published') RETURNING id INTO mod;
 INSERT INTO units(module_id,slug,title,description) VALUES(mod,'audit-unit','Synthetic fixture','Synthetic fixture') RETURNING id INTO unit;
 INSERT INTO lessons(unit_id,slug,title,description,difficulty,academic_level,estimated_duration_minutes,technical_review_status,publication_status) VALUES(unit,'staging-fluid-pressure','Synthetic fixture','Synthetic fixture','test','test',1,'Approved for student use','published') RETURNING id INTO lesson;
 INSERT INTO simulations(module_id,slug,title,description,technical_review_status,publication_status) VALUES(mod,'staging-hydraulic-cylinder','Synthetic fixture','Synthetic fixture','Approved for student use','published');
 INSERT INTO saved_lessons(student_profile_id,lesson_id) VALUES(a,lesson);
 INSERT INTO lesson_progress(student_profile_id,lesson_id) VALUES(a,lesson);
 INSERT INTO assessments(lesson_id,slug,title,description) VALUES(lesson,'audit-assessment','Synthetic fixture','No questions or answers') RETURNING id INTO assessment;
 INSERT INTO assessment_attempts(student_profile_id,assessment_id,status) VALUES(a,assessment,'in_progress') RETURNING id INTO attempt;
 PERFORM set_config('request.jwt.claims',json_build_object('sub',a,'role','authenticated')::text,true);
 SET LOCAL ROLE authenticated;
 SELECT count(*) INTO n FROM saved_lessons WHERE student_profile_id=a;
 RESET ROLE; PERFORM pg_temp.check_audit('DB-BOOKMARK-OWN',n=1,'A reads the seeded own bookmark (positive control).');
 SET LOCAL ROLE authenticated;
 denied:=false; BEGIN INSERT INTO saved_lessons(student_profile_id,lesson_id) VALUES(a,lesson) ON CONFLICT(student_profile_id,lesson_id) DO NOTHING; EXCEPTION WHEN insufficient_privilege THEN denied:=true; END;
 SELECT count(*) INTO n FROM saved_lessons WHERE student_profile_id=a;
 RESET ROLE; PERFORM pg_temp.check_audit('DB-BOOKMARK-LEGACY-PRESERVED',n=1 and denied,'Unreviewed legacy target cannot accept new saves; existing row is retained.');
 SET LOCAL ROLE authenticated;
 denied:=false; BEGIN UPDATE saved_lessons SET student_profile_id=b WHERE student_profile_id=a; EXCEPTION WHEN insufficient_privilege THEN denied:=true; END;
 RESET ROLE; PERFORM pg_temp.check_audit('DB-BOOKMARK-OWNER-CHANGE',denied,'A cannot transfer bookmark ownership.');
 SET LOCAL ROLE authenticated; SELECT count(*) INTO n FROM lesson_progress WHERE student_profile_id=a;
 RESET ROLE; PERFORM pg_temp.check_audit('DB-PROGRESS-OWN',n=1,'A reads its progress positive control.');
 SET LOCAL ROLE authenticated; SELECT count(*) INTO n FROM assessment_attempts WHERE id=attempt;
 RESET ROLE; PERFORM pg_temp.check_audit('DB-ATTEMPT-OWN',n=1,'A reads its attempt positive control.');
 PERFORM set_config('request.jwt.claims',json_build_object('sub',b,'role','authenticated')::text,true);
 SET LOCAL ROLE authenticated;
 SELECT count(*) INTO n FROM saved_lessons WHERE student_profile_id=a;
 RESET ROLE; PERFORM pg_temp.check_audit('DB-BOOKMARK-CROSS-READ',n=0,'B reads zero A bookmarks after A positive control.');
 SET LOCAL ROLE authenticated; UPDATE saved_lessons SET saved_at=now() WHERE student_profile_id=a; GET DIAGNOSTICS n=ROW_COUNT;
 RESET ROLE; PERFORM pg_temp.check_audit('DB-BOOKMARK-CROSS-UPDATE',n=0,'B updates zero A bookmarks.');
 SET LOCAL ROLE authenticated; DELETE FROM saved_lessons WHERE student_profile_id=a; GET DIAGNOSTICS n=ROW_COUNT;
 RESET ROLE; PERFORM pg_temp.check_audit('DB-BOOKMARK-CROSS-DELETE',n=0,'B deletes zero A bookmarks.');
 SET LOCAL ROLE authenticated; denied:=false; BEGIN INSERT INTO saved_lessons(student_profile_id,lesson_id) VALUES(a,lesson); EXCEPTION WHEN insufficient_privilege THEN denied:=true; END;
 RESET ROLE; PERFORM pg_temp.check_audit('DB-BOOKMARK-CROSS-INSERT',denied,'B cannot insert as A.');
 SET LOCAL ROLE authenticated; SELECT count(*) INTO n FROM lesson_progress WHERE student_profile_id=a;
 RESET ROLE; PERFORM pg_temp.check_audit('DB-PROGRESS-CROSS-READ',n=0,'B reads zero A progress rows.');
 SET LOCAL ROLE authenticated; SELECT count(*) INTO n FROM assessment_attempts WHERE id=attempt;
 RESET ROLE; PERFORM pg_temp.check_audit('DB-ATTEMPT-CROSS-READ',n=0,'B reads zero A attempts.');
 PERFORM set_config('request.jwt.claims',json_build_object('sub',a,'role','authenticated')::text,true);
 SET LOCAL ROLE authenticated; denied:=false; BEGIN UPDATE assessment_attempts SET score=100 WHERE id=attempt; EXCEPTION WHEN insufficient_privilege THEN denied:=true; END;
 RESET ROLE; PERFORM pg_temp.check_audit('DB-SCORE-DIRECT-WRITE',denied,'Ordinary authenticated SQL cannot overwrite attempt score.');
 SET LOCAL ROLE authenticated; denied:=false; BEGIN UPDATE lesson_progress SET percent_complete=100 WHERE student_profile_id=a; EXCEPTION WHEN insufficient_privilege THEN denied:=true; END;
 RESET ROLE; PERFORM pg_temp.check_audit('DB-PROGRESS-DIRECT-WRITE',denied,'Ordinary authenticated SQL cannot overwrite progress.');
 UPDATE profiles SET deleted_at=now() WHERE id=a;
 SET LOCAL ROLE authenticated; SELECT count(*) INTO n FROM lesson_progress WHERE student_profile_id=a;
 RESET ROLE; PERFORM pg_temp.check_audit('DB-DISABLED-DATA',n=0,'Disabled A reads '||n||' own progress rows through ordinary RLS.');
 SET LOCAL ROLE authenticated; denied:=false; n:=0; BEGIN UPDATE profiles SET deleted_at=null WHERE id=a; GET DIAGNOSTICS n=ROW_COUNT; EXCEPTION WHEN insufficient_privilege THEN denied:=true; END;
 RESET ROLE; PERFORM pg_temp.check_audit('DB-DISABLED-REENABLE',denied and n=0,'Blocked self-reactivation; updated rows='||n||'.');

 SET LOCAL ROLE authenticated; SELECT count(*) INTO n FROM profile_roles WHERE profile_id=a;
 RESET ROLE; PERFORM pg_temp.check_audit('DB-DISABLED-ROLES',n=0,'Existing JWT cannot read old role claims.');
 SET LOCAL ROLE authenticated; denied:=not public.has_role('student');
 RESET ROLE; PERFORM pg_temp.check_audit('DB-DISABLED-ROLE-HELPER',denied,'Authoritative helper rejects disabled actor.');
 SET LOCAL ROLE service_role; denied:=false; BEGIN PERFORM public.start_assessment_attempt_transaction(a,assessment,1,now()); EXCEPTION WHEN insufficient_privilege THEN denied:=true; END;
 RESET ROLE; PERFORM pg_temp.check_audit('DB-DISABLED-SERVICE-START',denied,'Service transaction rechecks active subject.');
 SET LOCAL ROLE service_role; denied:=false; BEGIN UPDATE assessment_attempts SET submitted_answers='[]' WHERE id=attempt; EXCEPTION WHEN insufficient_privilege THEN denied:=true; END;
 RESET ROLE; PERFORM pg_temp.check_audit('DB-DISABLED-SERVICE-UPDATE',denied,'Direct trusted persistence rechecks active subject.');
 SET LOCAL ROLE service_role; denied:=false; BEGIN PERFORM industrial_learn_private.start_assessment_attempt_transaction(a,assessment,1,now()); EXCEPTION WHEN insufficient_privilege THEN denied:=true; END;
 RESET ROLE; PERFORM pg_temp.check_audit('DB-INTERNAL-IMPLEMENTATION-DENIED',denied,'Internal function has no service/ordinary public access.');
 PERFORM set_config('request.jwt.claims',json_build_object('sub',own,'role','authenticated')::text,true);
 SET LOCAL ROLE authenticated; PERFORM set_profile_disabled(a,false,'Restore only rollback-only synthetic account');
 RESET ROLE; SELECT count(*) INTO n FROM profiles WHERE id=a AND deleted_at IS NULL; PERFORM pg_temp.check_audit('DB-MANAGER-RESTORE',n=1,'Audited manager RPC can restore active status.');
 SET LOCAL ROLE authenticated; SELECT count(*) INTO n FROM lesson_progress WHERE student_profile_id=a;
 RESET ROLE; PERFORM pg_temp.check_audit('DB-OWNER-NO-STUDENT-READ',n=0,'Owner role alone reads zero A progress rows.');
 SET LOCAL ROLE authenticated; denied:=false; BEGIN PERFORM record_content_review_decision(gen_random_uuid(),1,'audit','approved','Synthetic audit rejection test only','{}',ARRAY[]::text[],ARRAY[]::text[],'not_applicable'); EXCEPTION WHEN insufficient_privilege THEN denied:=true; END;
 RESET ROLE; PERFORM pg_temp.check_audit('DB-OWNER-NO-APPROVAL',denied,'Owner-only direct review RPC is denied before missing-target lookup.');
 PERFORM set_config('request.jwt.claims',json_build_object('sub',rev,'role','authenticated')::text,true);
 SET LOCAL ROLE authenticated; SELECT count(*) INTO n FROM lesson_progress WHERE student_profile_id=a;
 RESET ROLE; PERFORM pg_temp.check_audit('DB-REVIEWER-NO-STUDENT-READ',n=0,'Reviewer reads zero A progress rows.');

 PERFORM set_config('request.jwt.claims',json_build_object('sub',a,'role','authenticated')::text,true);
 SET LOCAL ROLE authenticated; SELECT count(*) INTO n FROM lesson_progress WHERE student_profile_id=a;
 RESET ROLE; PERFORM pg_temp.check_audit('DB-RESTORED-ACCESS',n=1,'Restored A regains its own progress positive control.');
 UPDATE profiles SET deleted_at=now() WHERE id=own;
 PERFORM set_config('request.jwt.claims',json_build_object('sub',own,'role','authenticated','app_role','platform_owner')::text,true);
 SET LOCAL ROLE authenticated; denied:=false; BEGIN PERFORM list_platform_users(); EXCEPTION WHEN insufficient_privilege THEN denied:=true; END;
 RESET ROLE; PERFORM pg_temp.check_audit('DB-DISABLED-MANAGER-RPC',denied,'Existing owner JWT and stale role claim cannot use privileged RPCs.');
 PERFORM set_config('request.jwt.claims',json_build_object('sub',gen_random_uuid(),'role','authenticated')::text,true);
 SET LOCAL ROLE authenticated; denied:=not is_active_profile(); SELECT count(*) INTO n FROM lesson_progress;
 RESET ROLE; PERFORM pg_temp.check_audit('DB-MISSING-STATUS',denied and n=0,'A missing authoritative profile never defaults to active.');
END $$;

DO $$ BEGIN IF EXISTS (SELECT 1 FROM audit_checks WHERE verdict <> 'PASS') THEN RAISE EXCEPTION 'Account security regressions failed'; END IF; END $$;
SELECT jsonb_agg(audit_checks) FROM audit_checks;
